package crypto
import("crypto/x509";"fmt";"os")
// VerifyServerCertificate checks exact Organization and the configured root chain.
func VerifyServerCertificate(raw [][]byte,rootPath,organization string)error{if len(raw)==0{return fmt.Errorf("server sent no certificate")};leaf,e:=x509.ParseCertificate(raw[0]);if e!=nil{return fmt.Errorf("parse server certificate: %w",e)};if len(leaf.Subject.Organization)==0||leaf.Subject.Organization[0]!=organization{return fmt.Errorf("server organization mismatch: got %q want %q",leaf.Subject.Organization,organization)};rb,e:=os.ReadFile(rootPath);if e!=nil{return fmt.Errorf("read root CA: %w",e)};roots:=x509.NewCertPool();if !roots.AppendCertsFromPEM(rb){return fmt.Errorf("load root CA")};inter:=x509.NewCertPool();for _,r:=range raw[1:]{c,e:=x509.ParseCertificate(r);if e!=nil{return fmt.Errorf("parse intermediate: %w",e)};inter.AddCert(c)};if _,e=leaf.Verify(x509.VerifyOptions{Roots:roots,Intermediates:inter,KeyUsages:[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth}});e!=nil{return fmt.Errorf("verify server chain: %w",e)};return nil}
